animation.css:
*{box-sizing:border-box}
i,b,em{font-style:normal;display:block}
.sc{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:14px 16px 10px;font-family:var(--sans);color:var(--fg)}
.nar{width:100%;max-width:540px;flex:none;display:flex;align-items:center;gap:9px;min-height:46px;padding:7px 12px;border-radius:12px;background:var(--glass);border:1px solid var(--hairline);font:600 13px/1.3 var(--sans)}
.nar b{flex:none;width:21px;height:21px;border-radius:50%;background:var(--brand);color:var(--brand-fg);font:600 11px/21px var(--mono);text-align:center;transition:background-color .4s,color .4s}
.nar.done b{background:var(--green);color:var(--bg)}
.row{width:100%;max-width:540px;flex:1;min-height:0;display:flex;align-items:center;gap:6px}
.phone{position:relative;flex:none;height:100%;max-height:230px;aspect-ratio:10/19;padding:5px;border-radius:24px;background:var(--card);border:1px solid var(--hairline-2);box-shadow:0 14px 32px -18px color-mix(in srgb,var(--fg) 30%,transparent)}
.scr{position:relative;height:100%;border-radius:19px;background:var(--bg-2);border:1px solid var(--hairline);padding:20px 9px 10px;display:flex;flex-direction:column;gap:6px;overflow:hidden}
.notch{position:absolute;top:7px;left:50%;width:30%;height:5px;margin-left:-15%;border-radius:4px;background:var(--hairline-2)}
.prod{aspect-ratio:16/11;border-radius:11px;background:var(--card-2);border:1px solid var(--hairline);display:flex;align-items:center;justify-content:center;font-size:clamp(20px,6vh,28px)}
.sk{height:5px;width:78%;border-radius:3px;background:var(--glass-2)}
.sk.s2{width:46%}
.fill{flex:1}
.st{display:flex;flex-direction:column;align-items:center;gap:5px;font:500 9.5px/1 var(--sans);color:var(--muted);white-space:nowrap;opacity:0;transform:translateY(4px);transition:opacity .3s cubic-bezier(.2,.7,.2,1),transform .3s cubic-bezier(.2,.7,.2,1)}
.st.on{opacity:1;transform:none}
.ic{position:relative;width:30px;height:30px}
.ic svg{position:absolute;inset:0;transform:rotate(-90deg)}
.ic circle{fill:none;stroke-width:2}
.ic b,.ic .nx{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:600 13px/1 var(--mono);color:var(--fg);opacity:0;transition:opacity .3s}
.ic .nx{font:700 12px/1 var(--sans);color:var(--red);border-radius:50%;background:var(--red-bg)}
.st[data-k=w] svg,.st[data-k=w] b,.st[data-k=n] .nx{opacity:1}
.ic svg{opacity:0;transition:opacity .3s}
.st[data-k=n]{color:var(--red)}
.rt{stroke:var(--hairline-2)}
.rf{stroke:var(--amber);stroke-dasharray:50.27;stroke-linecap:round}
.btn{position:relative;height:30px;flex:none;border-radius:10px;background:var(--brand);color:var(--brand-fg);font:600 11px/1 var(--sans);transition:background-color .4s cubic-bezier(.2,.7,.2,1),color .4s,transform .22s cubic-bezier(.2,.7,.2,1)}
.btn.press{transform:scale(.95)}
.btn[data-m=busy]{background:color-mix(in srgb,var(--brand) 14%,var(--card-2));color:var(--fg)}
.btn[data-m=done]{background:var(--green);color:var(--bg)}
.btn span{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:6px;white-space:nowrap;opacity:0;transform:translateY(5px);transition:opacity .3s cubic-bezier(.2,.7,.2,1),transform .35s cubic-bezier(.2,.7,.2,1)}
.btn[data-m=idle] .b-idle,.btn[data-m=busy] .b-busy,.btn[data-m=done] .b-done{opacity:1;transform:none}
.spin{width:9px;height:9px;border-radius:50%;border:1.5px solid color-mix(in srgb,var(--fg) 22%,transparent);border-top-color:var(--fg);animation:spin .9s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.tap{position:absolute;left:50%;top:50%;width:28px;height:28px;border-radius:50%;background:color-mix(in srgb,var(--fg) 22%,transparent);border:1.5px solid color-mix(in srgb,var(--fg) 55%,transparent);opacity:0;pointer-events:none}
.lane{position:relative;flex:1;min-width:48px;height:44px}
.dash{position:absolute;left:4px;right:4px;top:50%;border-top:1.5px dashed var(--hairline-2)}
.pk{position:absolute;top:50%;left:0;width:14px;height:14px;margin-top:-7px;border-radius:50%;background:var(--brand);box-shadow:0 0 0 4px color-mix(in srgb,var(--brand) 22%,transparent),0 0 16px color-mix(in srgb,var(--brand) 55%,transparent);opacity:0}
.pk em{position:absolute;left:50%;bottom:calc(100% + 8px);transform:translateX(-50%);padding:3px 6px;border-radius:6px;background:color-mix(in srgb,var(--brand) 20%,var(--card));color:var(--fg);font:500 10px/1 var(--mono);white-space:nowrap}
.pk.ok{width:18px;height:18px;margin-top:-9px;background:var(--green);color:var(--bg);font:700 10px/18px var(--sans);text-align:center;box-shadow:0 0 0 4px var(--green-bg),0 0 16px color-mix(in srgb,var(--green) 45%,transparent)}
.xm{position:absolute;right:2px;top:50%;width:18px;height:18px;margin-top:-9px;border-radius:50%;background:var(--red-bg);border:1px solid color-mix(in srgb,var(--red) 45%,transparent);color:var(--red);font:700 9px/16px var(--sans);text-align:center;opacity:0}
.shop{--c:var(--red);flex:none;width:88px;display:flex;flex-direction:column;align-items:center;gap:9px}
.shop[data-l=a]{--c:var(--amber)}
.shop[data-l=g]{--c:var(--green)}
.store{position:relative;width:74px;height:74px;border-radius:18px;background:var(--card);border:1px solid var(--hairline-2);display:flex;align-items:center;justify-content:center;box-shadow:0 0 0 5px color-mix(in srgb,var(--c) 14%,transparent);transition:box-shadow .6s cubic-bezier(.2,.7,.2,1)}
.store svg{width:46px;height:46px}
.a1{fill:var(--c);transition:fill .6s}
.a2{fill:color-mix(in srgb,var(--c) 40%,var(--card));transition:fill .6s}
.ln{fill:none;stroke:var(--muted);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.ln.w{fill:var(--glass-2)}
.badge{position:absolute;top:-8px;right:-8px;width:22px;height:22px;border-radius:50%;background:var(--green);color:var(--bg);font:700 11px/22px var(--sans);text-align:center;box-shadow:0 0 0 3px var(--bg-2);opacity:0;transform:scale(.4);transition:transform .45s cubic-bezier(.34,1.45,.64,1),opacity .25s}
.badge.on{opacity:1;transform:none}
.meter{display:flex;gap:3px}
.meter i{width:8px;height:5px;border-radius:3px;background:var(--hairline-2);transition:background-color .5s}
.meter i.on{background:var(--c)}
.tag{padding:4px 8px;border-radius:99px;background:color-mix(in srgb,var(--c) 14%,transparent);color:var(--c);font:600 10px/1 var(--sans);white-space:nowrap;transition:color .5s,background-color .5s}
.tl{width:100%;max-width:540px;height:30px;flex:none;display:flex;align-items:flex-start;padding:4px 2px 0}
.d{flex:none;width:16px;height:16px;border-radius:50%;border:1.5px solid var(--hairline-2);background:var(--bg-2);color:transparent;font:700 8px/13px var(--sans);text-align:center;transition:background-color .3s,border-color .3s,color .3s,box-shadow .4s cubic-bezier(.2,.7,.2,1)}
.d.now{border-color:var(--brand);background:var(--brand);box-shadow:0 0 0 4px color-mix(in srgb,var(--brand) 22%,transparent)}
.d.fail{border-color:color-mix(in srgb,var(--red) 55%,transparent);background:var(--red-bg);color:var(--red)}
.d.fail::before{content:"✕"}
.d.ok{border-color:var(--green);background:var(--green);color:var(--bg);box-shadow:0 0 0 4px var(--green-bg)}
.d.ok::before{content:"✓"}
.g{position:relative;flex-basis:0;height:4px;margin:6px 6px 0;border-radius:2px;background:var(--hairline)}
.g b{position:absolute;inset:0;border-radius:2px;background:var(--amber);transform-origin:left center;transform:scaleX(0)}
.g em{position:absolute;left:50%;top:9px;transform:translate(-50%,3px);font:500 10px/1 var(--mono);color:var(--muted);white-space:nowrap;opacity:0;transition:opacity .3s,transform .35s cubic-bezier(.2,.7,.2,1)}
.g em.on{opacity:1;transform:translate(-50%,0)}
@media (prefers-reduced-motion: reduce){
  *,*::before{animation:none!important;transition:none!important}
}

