animation.css:
.stage{position:relative;height:100%;display:flex;align-items:center;justify-content:center;gap:clamp(18px,6vw,72px);padding:0 12px;box-sizing:border-box;font-family:var(--sans);-webkit-font-smoothing:antialiased;user-select:none}
.phone{position:relative;flex:none;width:clamp(88px,24vw,148px);height:min(80%,260px);border-radius:clamp(16px,4vw,24px);background:var(--card-2);border:1px solid var(--hairline-2);padding:5px;box-sizing:border-box}
