.notch{flex:none;width:30%;height:4px;border-radius:4px;background:var(--hairline-2)}
.sk{flex:none;align-self:flex-start;height:5px;border-radius:3px;background:var(--glass-2)}
.venue{flex:1;width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:clamp(6px,1.6vw,10px)}
.arc{width:70%;height:7px;border-bottom:2px solid var(--hairline-2);border-radius:0 0 50% 50%/0 0 100% 100%}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(3px,1vw,6px);width:min(88%,104px)}
.grid>i{aspect-ratio:1;border-radius:3px;background:var(--hairline-2)}
.free{position:relative;display:block;aspect-ratio:1}
.free i{position:absolute;inset:0;border-radius:3px;will-change:transform,opacity}
.s-free{border:1.5px solid var(--brand);background:color-mix(in srgb,var(--brand) 22%,transparent);box-sizing:border-box}
.s-won{background:var(--green);opacity:0}
.s-gone{background:var(--hairline-2);opacity:0}
.bw{flex:none;position:relative;width:100%;height:clamp(26px,7vw,32px)}
.btn{position:absolute;inset:0;border-radius:9px;overflow:hidden;will-change:transform}
.btn b{position:absolute;inset:0;border-radius:inherit}
.bg-buy{background:var(--brand)}
.bg-ok{background:var(--green-bg);box-shadow:inset 0 0 0 1px var(--green);opacity:0}
.bg-no{background:var(--red-bg);box-shadow:inset 0 0 0 1px var(--red);opacity:0}
.t{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;white-space:nowrap;font-weight:600;font-size:clamp(10.5px,2.9vw,13px);letter-spacing:.01em}
.t-buy{color:var(--brand-fg)}
.t-ok{color:var(--green);opacity:0}
.t-no{color:var(--red);opacity:0}
.rip{position:absolute;left:50%;top:50%;width:40px;height:40px;margin:-20px 0 0 -20px;border-radius:50%;background:color-mix(in srgb,var(--brand-fg) 40%,transparent);opacity:0}
.tap{position:absolute;left:50%;top:50%;width:26px;height:26px;margin:-13px 0 0 -13px;border-radius:50%;box-sizing:border-box;background:color-mix(in srgb,var(--fg) 14%,transparent);border:1.5px solid color-mix(in srgb,var(--fg) 50%,transparent);opacity:0;z-index:3;will-change:transform,opacity}
.mid{flex:none;width:clamp(64px,16vw,112px);display:flex;flex-direction:column;align-items:center;gap:12px}
.slot{position:relative;width:100%;aspect-ratio:100/60}
.hole{position:absolute;inset:0;border-radius:10px;border:1.5px dashed var(--hairline-2);opacity:0}
.ring{position:absolute;inset:-9px;border-radius:16px;border:2px solid var(--brand);background:color-mix(in srgb,var(--brand) 7%,transparent);opacity:0;will-change:transform,opacity}
.pad{position:absolute;left:50%;top:-10px;width:24px;height:24px;margin:-12px 0 0 -12px;border-radius:50%;box-sizing:border-box;background:var(--card);border:1px solid var(--hairline-2);display:flex;align-items:center;justify-content:center;opacity:0}
.pl-sh{fill:none;stroke:var(--brand);stroke-width:2.2;stroke-linecap:round}
.pl-b{fill:var(--brand)}
.lbl{font-size:clamp(10.5px,2.7vw,12.5px);font-weight:500;color:var(--muted);white-space:nowrap;letter-spacing:.01em}
.fx{position:absolute;inset:0;pointer-events:none;z-index:2;overflow:hidden}
.tk{position:absolute;left:0;top:0;will-change:transform,opacity;filter:drop-shadow(0 6px 10px color-mix(in srgb,var(--brand) 30%,transparent))}
.tk svg{display:block}
.tk-b{fill:var(--brand)}
.tk-f{fill:var(--brand-fg)}
.tk-p{stroke:var(--brand-fg);stroke-width:1.4;stroke-dasharray:3 3;opacity:.55}
.tk-c{stroke:var(--brand-fg);stroke-width:2.4;stroke-linecap:round;opacity:.7}
.dot,.gh{position:absolute;left:0;top:0;border-radius:50%;opacity:0;will-change:transform,opacity}
.dot{width:10px;height:10px;margin:-5px 0 0 -5px}
.gh{width:8px;height:8px;margin:-4px 0 0 -4px}
.dot i{position:absolute;inset:0;border-radius:50%}
.c-b{background:var(--brand);box-shadow:0 0 0 4px color-mix(in srgb,var(--brand) 22%,transparent)}
.c-a{background:var(--amber);box-shadow:0 0 0 4px color-mix(in srgb,var(--amber) 24%,transparent);opacity:0}
.c-r{background:var(--red);box-shadow:0 0 0 4px color-mix(in srgb,var(--red) 22%,transparent);opacity:0}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

